export function translate(text: string, language: Language) {
  if (language === 'en') return text
  return translations[language][text] ?? text
}

export function localizeCountry(code: string, fallbackName: string, language: Language) {
  if (language === 'en') return fallbackName
  try {
    const displayName = new Intl.DisplayNames([language], { type: 'region' }).of(code.toUpperCase())
    return displayName || translate(fallbackName, language)
  } catch {
    return translate(fallbackName, language)
  }
}

type LocaleContextValue = { language: Language; setLanguage: (language: Language) => void; t: (text: string) => string }
const LocaleContext = createContext<LocaleContextValue>({ language: 'en', setLanguage: () => {}, t: (text) => text })

export function LocaleProvider({ children }: { children: ReactNode }) {
  const [language, setLanguage] = useState<Language>('en')
  const [localeReady, setLocaleReady] = useState(false)

  // Restore the chosen locale after hydration so server and first client markup match.
  /* eslint-disable react-hooks/set-state-in-effect */
  useEffect(() => {
    let saved: string | null = null
    try { saved = localStorage.getItem('northstar.language') } catch { /* Storage may be disabled. */ }
    if (!saved) saved = document.cookie.split('; ').find((cookie) => cookie.startsWith('northstar.language='))?.split('=')[1] ?? null
    if (saved && ['en', 'fr', 'es', 'zh', 'ru'].includes(saved)) setLanguage(saved as Language)
    setLocaleReady(true)
  }, [])
  /* eslint-enable react-hooks/set-state-in-effect */

  useEffect(() => {
    document.documentElement.lang = language
    try { document.cookie = `northstar.language=${language}; path=/; max-age=31536000; samesite=lax` } catch { /* Locale remains active for this session. */ }
    if (localeReady) {
      try { localStorage.setItem('northstar.language', language) } catch { /* Locale remains active for this session. */ }
    }
  }, [language, localeReady])

  const changeLanguage = (next: Language) => {
    setLanguage(next)
    try {
      localStorage.setItem('northstar.language', next)
      document.cookie = `northstar.language=${next}; path=/; max-age=31536000; samesite=lax`
    } catch { /* The selected locale still applies for this session. */ }
  }

  return (
    <LocaleContext.Provider value={{ language, setLanguage: changeLanguage, t: (text) => translate(text, language) }}>
      {children}
    </LocaleContext.Provider>
  )
}

export function useLocale() {
  return useContext(LocaleContext)
}
